<?php declare(strict_types=1);require_once dirname(__DIR__).'/auth_check.php';require_once dirname(__DIR__).'/bootstrap.php';$db=app_database();$view=(string)($_GET['view']??'');$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:'1900-01-01';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:'2999-12-31';$rows=[];$q=static function(string$sql,array$p=[])use($db){$s=$db->prepare($sql);$s->execute($p);return$s->fetchAll();};if(in_array($view,['real-in','unreserved-in'],true)){$rows=$q("SELECT 'Encaissement facture' label,e.reference_paiement reference,c.nom_client party,e.date_encaissement date,e.montant amount,'in' direction FROM encaissements e JOIN factures_clients f ON f.id=e.facture_id JOIN bons_commande bc ON bc.id=f.bon_commande_id LEFT JOIN client c ON c.id_client=bc.client_id WHERE e.date_encaissement BETWEEN :f AND :t UNION ALL SELECT CASE WHEN movement_type='manual_entry' THEN 'Nouvelle entrée réelle' ELSE 'Retour du disponible aux entrées' END,reference,note,movement_date,amount,'in' FROM treasury_ledger WHERE movement_type IN('manual_entry','return_to_entries') AND movement_date BETWEEN :f2 AND :t2 UNION ALL SELECT 'Transfert vers le disponible',reference,note,movement_date,amount,'out' FROM treasury_ledger WHERE movement_type='transfer_to_available' AND movement_date BETWEEN :f3 AND :t3",['f'=>$from,'t'=>$to,'f2'=>$from,'t2'=>$to,'f3'=>$from,'t3'=>$to]);}elseif($view==='available'){$rows=$q("SELECT CASE movement_type WHEN 'transfer_to_available' THEN 'Transfert des entrées réelles vers le disponible' WHEN 'return_to_entries' THEN 'Retour du disponible aux entrées' ELSE 'Sortie manuelle' END label,reference,note party,movement_date date,amount,CASE WHEN movement_type='transfer_to_available' THEN 'in' ELSE 'out' END direction FROM treasury_ledger WHERE movement_type IN('transfer_to_available','return_to_entries','manual_out') AND movement_date BETWEEN :f AND :t UNION ALL SELECT 'Décaissement FEB',reference_paiement,feb.numero_feb,date_decaissement,montant,'out' FROM decaissements d JOIN fiches_expression_besoin feb ON feb.id=d.feb_id WHERE date_decaissement BETWEEN :f2 AND :t2",['f'=>$from,'t'=>$to,'f2'=>$from,'t2'=>$to]);}elseif($view==='forecast-in'){$rows=$q("SELECT 'Facture à encaisser' label,f.numero_facture reference,c.nom_client party,COALESCE(f.expected_collection_date,f.date_echeance) date,GREATEST(f.montant_ttc-COALESCE(p.paid,0),0) amount,'in' direction FROM factures_clients f JOIN bons_commande bc ON bc.id=f.bon_commande_id LEFT JOIN client c ON c.id_client=bc.client_id LEFT JOIN(SELECT facture_id,SUM(montant)paid FROM encaissements GROUP BY facture_id)p ON p.facture_id=f.id WHERE f.collection_tracking_status<>'cancelled' AND (COALESCE(f.expected_collection_date,f.date_echeance) BETWEEN :f AND :t OR COALESCE(f.expected_collection_date,f.date_echeance)<:f2)",['f'=>$from,'t'=>$to,'f2'=>$from]);}elseif($view==='reserved'){$rows=$q("SELECT 'Réservation FEB' label,feb.numero_feb reference,c.nom_client party,fp.scheduled_date date,fp.amount,'out' direction FROM feb_funding_plans fp JOIN fiches_expression_besoin feb ON feb.id=fp.feb_id JOIN bons_commande bc ON bc.id=feb.bon_commande_id LEFT JOIN client c ON c.id_client=bc.client_id WHERE fp.status IN('planned','closed')");}elseif($view==='validation-purchase'){$rows=$q("SELECT 'Validation achat' label,da.authorization_number reference,da.beneficiary_name party,da.planned_date date,da.amount,'out' direction FROM disbursement_authorizations da WHERE da.status='purchase_validation'");}elseif(in_array($view,['real-out','forecast-out'],true)){$op=$view==='real-out'?'<=':'>';$rows=$q("SELECT 'FEB planifiée' label,feb.numero_feb reference,da.beneficiary_name party,fp.scheduled_date date,fp.amount,'out' direction FROM feb_funding_plans fp JOIN fiches_expression_besoin feb ON feb.id=fp.feb_id JOIN disbursement_authorizations da ON da.feb_id=feb.id WHERE fp.status='planned' AND fp.scheduled_date $op :to",['to'=>$to]);}elseif($view==='projected-out'){$rows=$q("SELECT CONCAT('Déboursé · ',dl.designation) label,bc.numero_bc reference,c.nom_client party,p.date_debut date,dl.montant amount,'out' direction FROM debourse_lignes dl JOIN debourses d ON d.id=dl.debourse_id JOIN bons_commande bc ON bc.id=d.bon_commande_id LEFT JOIN client c ON c.id_client=bc.client_id LEFT JOIN planning_affaire p ON p.bon_commande_id=bc.id");}header('Content-Type: application/json; charset=UTF-8');echo json_encode(['rows'=>$rows],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
